import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { HealthService } from '../../services/health.service';
import { AuthService } from '../../services/auth.service';
import { HealthData, UploadProgress, TotalStats } from '../../models/health-data.model';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.scss']
})
export class DashboardComponent implements OnInit {
  healthData: HealthData[] = [];
  latestUpload: HealthData | null = null;
  totalStats: TotalStats | null = null;
  isLoading = true;
  username = '';

  constructor(
    private healthService: HealthService,
    private authService: AuthService,
    private router: Router
  ) { }

  ngOnInit(): void {
    // Get user email from JWT token using AuthService
    this.username = this.authService.getUserEmail() || 'user';

    this.loadHealthData();
  }

  loadHealthData(): void {
    this.isLoading = true;
    this.healthService.getHealthData().subscribe({
      next: (data: HealthData[]) => {
        this.healthData = data;
        this.latestUpload = this.getLatestUpload(data);
        this.totalStats = this.calculateTotalStats(data);
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Error loading health data:', error);
        this.isLoading = false;
      }
    });
  }

  getLatestUpload(data: HealthData[]): HealthData | null {
    if (data.length === 0) return null;
    // Sort by date descending and return the most recent upload
    const sortedData = [...data].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    return sortedData[0];
  }

  calculateTotalStats(data: HealthData[]): TotalStats {
    const validUploads = data.filter(d => d.steps !== null || d.calories !== null);
    const totalUploads = validUploads.length;
    const totalSteps = validUploads.reduce((sum, d) => sum + (d.steps || 0), 0);
    const totalCalories = validUploads.reduce((sum, d) => sum + (d.calories || 0), 0);

    return {
      totalSteps,
      totalCalories,
      totalUploads,
      averageSteps: totalUploads > 0 ? Math.round(totalSteps / totalUploads) : 0,
      averageCalories: totalUploads > 0 ? Math.round(totalCalories / totalUploads) : 0
    };
  }

  calculateAverage(values: (number | null)[]): number {
    const validValues = values.filter(v => v !== null) as number[];
    return validValues.length > 0 ? validValues.reduce((sum, v) => sum + v, 0) / validValues.length : 0;
  }

  goToUpload(): void {
    this.router.navigate(['/upload']);
  }

  goHome(): void {
    this.router.navigate(['/']);
  }

  formatValue(value: number | null): string {
    if (value === null || value === undefined) return 'N/A';
    return value.toLocaleString();
  }

  formatDate(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric' 
    });
  }

  roundValue(value: number): number {
    return Math.round(value);
  }

  convertCaloriesToKcal(calories: number | null): number {
    if (calories === null || calories === undefined) return 0;
    return Math.round(calories / 1000 * 100) / 100; // Round to 2 decimal places
  }

  formatCalories(calories: number | null): string {
    if (calories === null || calories === undefined) return 'N/A';
    return calories.toLocaleString();
  }

  formatKcal(calories: number | null): string {
    if (calories === null || calories === undefined) return 'N/A';
    const kcal = this.convertCaloriesToKcal(calories);
    return kcal.toFixed(2);
  }

}
<div class="min-h-screen flex flex-col">
  <app-header></app-header>

  <main class="flex-1 px-4 py-6">
    <!-- Header -->
    <div class="flex items-center justify-between mb-6">
      <div>
        <h1 class="text-2xl font-bold text-white">Dashboard</h1>
        <p class="text-white/80">
          <span *ngIf="username; else noUser">{{ username }} - Securely connected via Clienta app</span>
          <ng-template #noUser>Welcome back! Securely connected via Clienta app</ng-template>
        </p>
      </div>
      <button 
        (click)="goToUpload()"
        class="btn-primary flex items-center space-x-2">
        <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/>
        </svg>
        <span>Add Data</span>
      </button>
    </div>

    <!-- Loading State -->
    <div *ngIf="isLoading" class="flex items-center justify-center py-12">
      <div class="animate-spin rounded-full h-12 w-12 border-b-2 border-white"></div>
    </div>

    <!-- Dashboard Content -->
    <div *ngIf="!isLoading" class="space-y-6">
      <!-- Latest Upload -->
      <div class="bg-gradient-to-br from-cyan/95 to-dark-cyan/90 backdrop-blur-sm rounded-2xl shadow-xl border border-cyan/30 p-6 text-white">
        <h2 class="text-xl font-semibold text-white mb-4 flex items-center">
          <svg class="w-6 h-6 text-white mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/>
          </svg>
          Latest Upload
        </h2>

        <div *ngIf="latestUpload; else noUploads" class="grid grid-cols-2 gap-4">
          <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
            <div class="text-3xl font-bold text-white mb-1">{{ formatValue(latestUpload.steps) }}</div>
            <div class="text-sm text-white/80">Steps</div>
          </div>
          <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
            <div class="text-3xl font-bold text-white mb-1">{{ formatValue(latestUpload.calories) }}</div>
            <div class="text-sm text-white/80">Calories</div>
          </div>
        </div>

        <ng-template #noUploads>
          <div class="text-center py-8">
            <div class="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <svg class="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/>
              </svg>
            </div>
            <h3 class="text-lg font-semibold text-white mb-2">No uploads yet</h3>
            <p class="text-white/80 mb-4">Upload your first fitness screenshot to get started!</p>
            <button (click)="goToUpload()" class="btn-primary">
              Upload Data
            </button>
          </div>
        </ng-template>
      </div>

      <!-- Total Stats -->
      <div *ngIf="totalStats" class="bg-gradient-to-r from-dark-grey/90 to-grey/80 backdrop-blur-sm rounded-2xl shadow-xl border border-grey/30 p-6 text-white">
        <h2 class="text-xl font-semibold text-white mb-4 flex items-center">
          <svg class="w-6 h-6 text-cyan mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/>
          </svg>
          Total Stats ({{ totalStats.totalUploads }} uploads)
        </h2>

        <div class="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
            <div class="text-2xl font-bold text-white mb-1">{{ formatValue(totalStats.totalSteps) }}</div>
            <div class="text-sm text-white/80">Total Steps</div>
          </div>
          <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
            <div class="text-2xl font-bold text-white mb-1">{{ formatValue(totalStats.totalCalories) }}</div>
            <div class="text-sm text-white/80">Total Calories</div>
          </div>
          <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
            <div class="text-2xl font-bold text-white mb-1">{{ formatValue(totalStats.averageSteps) }}</div>
            <div class="text-sm text-white/80">Avg Steps</div>
          </div>
          <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
            <div class="text-2xl font-bold text-white mb-1">{{ formatValue(totalStats.averageCalories) }}</div>
            <div class="text-sm text-white/80">Avg Calories</div>
          </div>
        </div>
      </div>

      <!-- All Uploads -->
      <div *ngIf="healthData.length > 0" class="bg-gradient-to-br from-cyan/95 to-dark-cyan/90 backdrop-blur-sm rounded-2xl shadow-xl border border-cyan/30 p-6 text-white">
        <h2 class="text-xl font-semibold text-white mb-4 flex items-center">
          <svg class="w-6 h-6 text-white mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/>
          </svg>
          All Uploads ({{ healthData.length }})
        </h2>

        <div class="space-y-3 max-h-96 overflow-y-auto">
          <div *ngFor="let data of healthData.slice().reverse(); let i = index" 
               class="flex items-center justify-between p-3 bg-white/20 rounded-xl backdrop-blur-sm border border-white/30">
            <div class="flex items-center space-x-3">
              <div class="w-10 h-10 bg-gradient-to-br from-dark-cyan/40 to-cyan/30 rounded-xl flex items-center justify-center shadow-lg">
                <span class="text-sm font-bold text-white">#{{ healthData.length - i }}</span>
              </div>
              <div>
                <p class="font-medium text-white">Upload #{{ healthData.length - i }}</p>
                <p class="text-sm text-white/80">{{ formatValue(data.steps) }} steps</p>
                <p class="text-xs text-white/60">{{ formatDate(data.date) }}</p>
              </div>
            </div>
            <div class="text-right">
              <p class="text-sm font-medium text-white">{{ formatValue(data.calories) }}</p>
              <p class="text-xs text-white/70">calories</p>
            </div>
          </div>
        </div>
      </div>

      <!-- Empty State -->
      <div *ngIf="healthData.length === 0" class="bg-gradient-to-r from-dark-grey/90 to-grey/80 backdrop-blur-sm rounded-2xl shadow-xl border border-grey/30 p-6 text-white text-center py-12">
        <div class="w-20 h-20 bg-gradient-to-br from-cyan/30 to-dark-cyan/40 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-lg">
          <svg class="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/>
          </svg>
        </div>
        <h3 class="text-xl font-semibold text-white mb-2">Start Your Health Journey</h3>
        <p class="text-white/80 mb-6">Upload your first fitness screenshot to begin tracking your progress</p>
        <button (click)="goToUpload()" class="btn-primary">
          Upload First Data
        </button>
      </div>
    </div>

    <!-- Bottom Navigation -->
    <div class="flex justify-center mt-8">
      <button (click)="goHome()" class="btn-secondary">
        Back to Home
      </button>
    </div>
  </main>
</div>
